using System.Collections.Generic;using UnityEngine;public class RouteRenderer:MonoBehaviour{[SerializeField] GameObject arrowPrefab;public void Render(IReadOnlyList<Vector3> points){foreach(Transform c in transform)Destroy(c.gameObject);for(int i=0;i<points.Count;i++){var a=Instantiate(arrowPrefab,points[i],Quaternion.identity,transform);if(i<points.Count-1)a.transform.LookAt(points[i+1]);}}}
